		local carry = bit32_rshift(lo, 32 - rhs)

		return into_bits_i64(bit32_lshift(lo, rhs), bit32_or(bit32_lshift(hi, rhs), carry))
	end

	if rhs == 32 then
		return into_bits_i64(0, lo)
