	local c0 = digit0 % 0x10000
	carry = math.floor(digit0 / 0x10000)

	local digit1 = carry + a0 * b1 + a1 * b0
	local c1 = digit1 % 0x10000
	carry = math.floor(digit1 / 0x10000)

